import java.util.LinkedHashMap;
import java.util.Map;

class Menu {
    private final Map<String, Integer> prices = Map.of("tea", 15, "dosa", 40, "idli", 30);

    int price(String item) {
        return prices.getOrDefault(item, 0);
    }
}

class Order {
    private final Map<String, Integer> items = new LinkedHashMap<>();

    void add(String item, int qty) {
        items.merge(item, qty, Integer::sum);
    }

    int total(Menu menu) {
        int sum = 0;
        for (var e : items.entrySet()) {
            sum += menu.price(e.getKey()) * e.getValue();
        }
        return sum;
    }
}

public class Main {
    public static void main(String[] args) {
        Menu menu = new Menu();
        Order order = new Order();
        order.add("dosa", 1);
        order.add("tea", 2);
        order.add("tea", 1);
        System.out.println("Bill: Rs " + order.total(menu));
    }
}

