class Coupon {
    private final int percent;

    Coupon(int percent) {
        this.percent = percent;
    }

    int apply(int amount) {
        return amount - amount * percent / 100;
    }
}

public class Main {
    public static void main(String[] args) {
        int bill = 85;
        System.out.println("Pay: Rs " + new Coupon(10).apply(bill));
    }
}

