import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

class Student {
    private final String name;
    private final Map<String, Integer> marks = new HashMap<>();

    Student(String name) {
        this.name = name;
    }

    String getName() {
        return name;
    }

    void addMark(String subject, int mark) {
        if (mark < 0 || mark > 100) {
            throw new IllegalArgumentException("bad mark: " + mark);
        }
        marks.put(subject, mark);
    }

    double average() {
        return marks.values().stream().mapToInt(m -> m).average().orElse(0);
    }

    boolean passed() {
        return marks.values().stream().allMatch(m -> m >= 35);
    }
}

class ResultBook {
    private final Map<String, Student> students = new TreeMap<>();

    void add(String line) {
        String[] f = line.split(",");
        if (f.length != 3) {
            return;
        }
        try {
            int mark = Integer.parseInt(f[2].trim());
            Student s = students.getOrDefault(f[0], new Student(f[0]));
            s.addMark(f[1], mark);
            students.putIfAbsent(f[0], s);
        } catch (IllegalArgumentException e) {
            // skip a bad line (not a number, or out of range)
        }
    }

    List<String> report() {
        List<String> out = new ArrayList<>();
        for (Student s : students.values()) {
            out.add(s.getName() + ": " + String.format("%.1f", s.average()) + ", " + (s.passed() ? "PASS" : "FAIL"));
        }
        return out;
    }
}

public class Main {
    public static void main(String[] args) {
        List<String> lines = List.of("Sita,Maths,30", "Ravi,Maths,80", "Ravi,Physics,71", "Anu,Maths,abc", "Anu,Physics,150");
        ResultBook book = new ResultBook();
        lines.forEach(book::add);
        book.report().forEach(System.out::println);
    }
}
